#include <bits/stdc++.h>
using namespace std;


void solve(){
    int n,k;cin >> n >> k;
    
    string s;cin >> s;
    
    if(count(s.begin(),s.end(),'G') <= k+1){
        cout << "YES\n";
        return;
    }
    
    int g = 0;
    int idx = -1;
    for(int i=0;i<n;i++){
       if(s[i]=='G')g++;
       if(g==k+1){
           idx = i+1;
           break;
       }
    }
    int idx2 = -1;
    for(int i=idx;i<n;i++){
        if(s[i]=='G'){idx2 = i+1;break;}    
    }
    
    if(idx2==-1){
        cout << "YES\n";
        return;
    }
    
    int wt = k;
    int idx3 = -1;
    for(int i=idx2;i<n;i++){
        if(s[i]=='G')wt-=1;
        else wt-=2;
    }
    if(wt < 0){
        cout << "NO\n";
    }
    else{
        cout << "YES\n";
    }
}

int main() {
	// your code goes here
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;cin >> t;
    while(t--)solve();
    return 0;
}
